#!/bin/bash\nset -e\n\necho \"🚀 Deploying to STAGING environment...\"\n\n# Get environment variables\nIMAGE_TAG=${IMAGE_TAG:-latest}\nENVIRONMENT=staging\n\necho \"📋 Deployment Info:\"\necho \"  Environment: $ENVIRONMENT\"\necho \"  Image Tag: $IMAGE_TAG\"\necho \"  Timestamp: $(date)\"\n\n# Pull latest images\necho \"📦 Pulling Docker images...\"\ndocker pull $REGISTRY/$BACKEND_IMAGE:$IMAGE_TAG\ndocker pull $REGISTRY/$FRONTEND_IMAGE:$IMAGE_TAG\n\n# Stop old containers\necho \"⏹️  Stopping old containers...\"\ndocker-compose -f docker-compose.yml -f docker-compose.staging.yml down || true\n\n# Set environment\nexport BACKEND_IMAGE_TAG=$IMAGE_TAG\nexport FRONTEND_IMAGE_TAG=$IMAGE_TAG\nexport ENVIRONMENT=staging\n\n# Deploy new containers\necho \"🚀 Starting new containers...\"\ndocker-compose -f docker-compose.yml -f docker-compose.staging.yml up -d\n\n# Run migrations\necho \"🔄 Running database migrations...\"\ndocker-compose exec -T backend alembic upgrade head || echo \"⚠️  Migrations skipped\"\n\n# Wait for services to be ready\necho \"⏳ Waiting for services to be ready...\"\nsleep 10\n\n# Health checks\necho \"✅ Running health checks...\"\nfor i in {1..5}; do\n  if docker-compose exec -T backend curl -f http://localhost:8000/health > /dev/null 2>&1; then\n    echo \"✅ Backend health check passed\"\n    break\n  fi\n  echo \"⏳ Attempt $i/5, waiting...\"\n  sleep 5\ndone\n\necho \"✅ Staging deployment completed successfully!\"\necho \"📍 Access: https://staging.synapzcommerce.dev\"\n"